function exportErrorMessage(message){const text=String(message||'3D export failed.');if(!/zero area/i.test(text))return text;return text.replace(/Try smoother tracing\.?/i,'').replace(/\.\s*\./g,'.').trim()+' Increase Maximum colors (for example, from 4 to 6 or 8), then retrace your artwork and rebuild the 3D model. Increasing colors can help separate merged details.';}
function stlSettings(){const values={widthMM:+$('modelWidth').value,baseMM:+$('baseHeight').value,topMM:+$('topHeight').value};for(const [key,n]of Object.entries(values))if(!Number.isFinite(n)||n<=0||n>({widthMM:500,baseMM:20,topMM:10}[key]))throw Error('Use a width of 1–500 mm, base of 0.1–20 mm and raised layer of 0.1–10 mm.');if(values.widthMM<1||values.baseMM<.1||values.topMM<.1)throw Error('Model dimensions are too small.');return values;}
function clearSTL(item){for(const key of ['stlUrl','partsUrl','threeMFUrl'])if(item[key])URL.revokeObjectURL(item[key]);item.threeMFUrl=null;item.threeMF=null;item.stlUrl=null;item.partsUrl=null;item.stl=null;item.stlError=null;}
function makeSTL(svg,settings){return new Promise((resolve,reject)=>{const doc=new DOMParser().parseFromString(svg,'image/svg+xml');const box=(doc.documentElement.getAttribute('viewBox')||'').split(/[ ,]+/).map(Number);const metadata=doc.querySelector('#coasterprint-trace');let perimeterD='',perimeterMaskD='',perimeterFill='',perimeterRimPx=0;if(metadata){try{const trace=JSON.parse(metadata.textContent);if(trace.perimeterPathID){perimeterD=doc.getElementById(trace.perimeterPathID)?.getAttribute('d')||'';perimeterMaskD=doc.getElementById(trace.perimeterMaskPathID)?.getAttribute('d')||'';perimeterFill=trace.perimeterFill;perimeterRimPx=+trace.perimeterRimPx||0;}}catch{}}const paths=[...doc.querySelectorAll('path')].filter(p=>!p.closest('defs')&&p.getAttribute('fill')!=='none'&&p.getAttribute('opacity')!=='0').map(p=>({d:p.getAttribute('d'),fill:p.getAttribute('fill')||'#000000',fillRule:p.getAttribute('fill-rule')||'nonzero'}));const worker=new Worker('stl-worker.c39bad7631d4.js',{type:'module'});const timer=setTimeout(()=>{worker.terminate();reject(Error('STL generation timed out. Try fewer colors or smoother tracing.'));},180000);const finish=()=>{clearTimeout(timer);worker.terminate();};worker.onmessage=e=>{finish();e.data.error?reject(Error(e.data.error)):resolve(e.data);};worker.onerror=e=>{finish();reject(Error('Could not load the 3D engine. Serve the app over HTTP/HTTPS and allow WebAssembly.'));};worker.postMessage({paths,perimeterD,perimeterMaskD,perimeterFill,perimeterRimPx,viewWidth:box[2],...settings});});}
function partsArchive(item,result){const files={};const baseName='base-'+result.baseMM+'mm.stl';files[baseName]=new Uint8Array(result.base.buffer);const colors=result.parts.map(part=>{const rgb=(part.fill.match(/[\d.]+/g)||[]).slice(0,3).map(Number);const hex=rgb.length===3?'#'+rgb.map(n=>Math.round(n).toString(16).padStart(2,'0')).join(''):part.fill;const name='image-color-'+String(part.index).padStart(2,'0')+'-'+hex.replace('#','')+'.stl';files[name]=new Uint8Array(part.buffer);return {file:name,svgColor:part.fill,hex,zStartMM:result.baseMM,heightMM:result.topMM};});files['colors.json']=fflate.strToU8(JSON.stringify({units:'mm',dimensions:result.dimensions,base:{file:baseName,zStartMM:0,heightMM:result.baseMM},colors},null,2));files['IMPORT-INTO-BAMBU.txt']=fflate.strToU8('COASTERPRINT — ALIGNED PRINT PARTS\n\nExtract this ZIP. Select the base STL and ALL image-color STL files, then drag them into Bambu Studio together. When asked, load them as a SINGLE object with multiple parts. This preserves the shared coordinates and the raised layer height. Do not import or auto-arrange each file separately: the slicer may drop each part onto the plate.\n\nAssign a filament to the base and each image color part. colors.json lists the SVG colors. STL itself stores geometry, not colors.\n\nBase: '+result.baseMM+' mm, Z=0 to '+result.baseMM+'. Raised image: '+result.topMM+' mm, Z='+result.baseMM+' to '+(result.baseMM+result.topMM)+'. Width: '+result.widthMM+' mm.\n\nThe combined STL is a separate single-material download. When the raised image covers the entire base, the combined file is a flat-topped plaque: the separate color parts preserve the image for multi-filament printing.\n');return fflate.zipSync(files,{level:6});}
async function generateItemSTL(item,settings){clearSTL(item);try{const result=await makeSTL(item.svg,settings);if(result.warnings)result.warnings=result.warnings.map(exportErrorMessage);item.stl=result;item.threeMF=make3MF(result);item.threeMFUrl=URL.createObjectURL(new Blob([item.threeMF],{type:'model/3mf'}));if(result.combined)item.stlUrl=URL.createObjectURL(new Blob([result.combined.buffer],{type:'model/stl'}));item.partsUrl=URL.createObjectURL(new Blob([partsArchive(item,result)],{type:'application/zip'}));}catch(e){clearSTL(item);item.stlError=exportErrorMessage(e.message);} }
async function generateAllSTLs(){if(busy)return;const ready=items.filter(i=>i.svg&&!i.traceStale);if(!ready.length)return;let settings;try{settings=stlSettings();}catch(e){$('notice').textContent=e.message;return;}busy=true;render();for(let n=0;n<ready.length;n++){$('notice').textContent='Building 3D model '+(n+1)+' of '+ready.length+'…';await generateItemSTL(ready[n],settings);render();}busy=false;const failed=ready.filter(i=>i.stlError).length;$('notice').textContent=failed?ready.filter(i=>i.stlError).map(i=>i.file.name+': '+i.stlError).join(' | '):'3D models ready: '+settings.baseMM+' mm base + '+settings.topMM+' mm raised image.';render();}
$('buildSTL').onclick=generateAllSTLs;
$('downloadSTL').onclick=()=>{const ready=items.filter(i=>i.stl&&i.stl.combined);if(ready.length===1){download(ready[0].stlUrl,ready[0].outname.replace(/\.svg$/,'.stl'));return;}const files={};for(const item of ready){const name=item.outname.replace(/\.svg$/,'');files[name+'.3mf']=item.threeMF;files[name+'.stl']=new Uint8Array(item.stl.combined.buffer);files[name+'-color-parts.zip']=partsArchive(item,item.stl);}const url=URL.createObjectURL(new Blob([fflate.zipSync(files,{level:6})],{type:'application/zip'}));download(url,'coasterprint-3d-models.zip');setTimeout(()=>URL.revokeObjectURL(url),30000);};
for(const id of ['modelWidth','baseHeight','topHeight'])$(id).addEventListener('input',()=>{for(const item of items)clearSTL(item);render();$('notice').textContent='3D dimensions changed. Click Build / rebuild STL to apply.';});

$('download3MF').onclick=()=>{const ready=items.filter(i=>i.threeMF);if(ready.length>1){downloadBatchProject();return;}if(ready.length===1){download(ready[0].threeMFUrl,ready[0].outname.replace(/\.svg$/,'.3mf'));return;}const files={};for(const item of ready)files[item.outname.replace(/\.svg$/,'.3mf')]=item.threeMF;const url=URL.createObjectURL(new Blob([fflate.zipSync(files,{level:6})],{type:'application/zip'}));download(url,'coasterprint-bambu-models.zip');setTimeout(()=>URL.revokeObjectURL(url),30000);};
